// <work-chart> — THE data-viz reinvention: a chart IS a view over a query, not a
// client-side data-wrangling widget. Aggregation / binning / grouping run IN the
// shared engine (DuckDB on the runtime tier · browser duckdb-wasm · the in-JS
// subset offline) — the element issues SQL and renders the result. Reach compute
// ONLY through the src/data layer (getEngine), exactly like the sibling
// <work-table>. Composition-as-source: the chart carries its data + query as source.
//
// TWO render tiers behind ONE public API (attrs / events / data path identical):
//   • FLOOR — zero-dependency SVG, themed entirely from --work-* (axes, gridlines,
//     marks, legend, tooltip). The guaranteed render; never blocks on a network.
//   • POWERED — Observable Plot (./plot-tier.js), lazy-loaded from a CDN ESM at
//     runtime (overridable via window.__WB_PLOT__). Draws the SAME logical chart
//     (same _layout() model) with Plot, themed from the SAME --work-* tokens.
//   The tier resolves per-draw: `engine="plot"|"floor"` attr or
//   window.__WB_CHART_ENGINE__ force it; default "auto" prefers Plot and falls
//   back to the floor instantly if the lazy import fails (offline / blocked).
//
// Renders zero-dependency SVG themed entirely from --work-* (axes, gridlines, marks,
// legend, tooltip). Responsive (re-renders on resize). The element does NO data
// wrangling: it maps a WbQueryResult { columns, rows[i][j], types } to marks by
// the x / y / series column attributes, and nothing more.
//
// Re-based onto Lit: render() returns the Lit shell (wrapping the string-built
// chrome via unsafeHTML); the SVG itself is drawn imperatively in _draw(), invoked
// from Lit's updated() hook and on resize. The _load single-flight + stable inline
// auto-name + whenRegistered/register plumbing is unchanged.
//
// Usage (register elsewhere, aggregate IN the engine):
//   <work-chart type="bar" src-name="orders" x="region" y="revenue"
//     query="SELECT region, sum(revenue) AS revenue FROM orders GROUP BY region"></work-chart>
//
// Usage (named source, default SELECT — x/y pick columns off the result):
//   <work-chart type="line" src-name="daily" x="day" y="visits"></work-chart>
//
// Usage (bind to a <work-query> by name — the canonical data binding):
//   <work-query name="daily" sql="SELECT day, visits FROM events"></work-query>
//   <work-chart type="line" from="daily" x="day" y="visits"></work-chart>
//
// Usage (inline data, no engine round-trip beyond registration):
//   <work-chart type="scatter" x="x" y="y" rows='[{"x":1,"y":3},{"x":2,"y":5}]'></work-chart>
//
// Attributes:
//   type        bar | line | area | scatter | pie   (the chart variant)
//   from        name of a <work-query> dataset to read (the canonical binding)
//   src-name    name of a source registered via getEngine().register(...)
//   query       full SQL to run (the aggregate/GROUP BY lives HERE, in the engine)
//   rows        inline JSON array of row objects (registers an auto-named source)
//   csv         inline CSV text (header row) → auto-named source
//   x           column for the category / x axis (default: first column)
//   y           column(s) for the value axis — comma-separated for multi-series
//   series      a column whose distinct values become series (long → wide, in JS
//               layout only; the values themselves come straight from the result)
//   label       pie: slice-label column (default = x); value = y
//   size        sm | md | lg     (chart height preset)
//   variant     card | bare      (visual shell)
//   engine      auto | plot | floor   (render tier — see below)
//   legend      auto | off       (default auto: shown when >1 series)
//   format      usd | num | pct | none   (value formatting in axis + tooltip)
//   title       optional heading rendered in the shell
//
// Events:
//   work-chart-ready   { detail: { type, columns, types, engine, series, rowCount } }
//   work-chart-query   { detail: { sql, rowCount, engine } }      on every (re)query
//   work-point-select  { detail: { series, x, y, row, index } }   on hover/click a mark
import { WbElement, html, css, define } from "../../core/element.js";
import { unsafeHTML } from "lit/directives/unsafe-html.js";
import { defineVariants, variantAttrs, resolveVariant } from "../../core/variants.js";
import { getEngine } from "../../data/index.js";
import { loadPlot, readTokens, renderPlot } from "./plot-tier.js";

const VARIANTS = defineVariants({
  type: { options: ["bar", "line", "area", "scatter", "pie"], default: "bar" },
  size: { options: ["sm", "md", "lg"], default: "md" },
  variant: { options: ["card", "bare"], default: "card" },
});

const HEIGHTS = { sm: 180, md: 300, lg: 440 };
// Categorical palette — pastel chips first, then brand/state tokens. Pure tokens.
const PALETTE = [
  "var(--work-brand)", "var(--work-chip-blue)", "var(--work-chip-peach)",
  "var(--work-chip-lavender)", "var(--work-chip-green)", "var(--work-warn)",
  "var(--work-ok)", "var(--work-err)",
];

let _autoId = 0;

export class WbChart extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "src-name", "from", "query", "rows", "csv",
    "x", "y", "series", "label", "legend", "format", "title",
    "engine",   // tier override: auto (default, prefer Plot) | plot | floor
  ];

  static styles = css`
    :host { display: block; font-family: var(--work-font); color: var(--work-fg); }
    .shell { border: 1px solid var(--work-border); border-radius: var(--work-radius);
      background: var(--work-surface); overflow: hidden; box-shadow: var(--work-shadow-sm); }
    :host([variant="bare"]) .shell { border: none; box-shadow: none; background: transparent; }

    .head { display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-3) var(--work-space-4) 0; }
    .title { font-family: var(--work-font-display, var(--work-font)); font-weight: 600;
      font-size: var(--work-text-lg); letter-spacing: -0.01em; }
    .grow { flex: 1; }
    .engine { display: inline-flex; align-items: center; gap: var(--work-space-1);
      font-family: var(--work-font-mono); font-size: var(--work-text-sm); color: var(--work-fg-subtle); }
    .dot { width: 7px; height: 7px; border-radius: var(--work-radius-pill); background: var(--work-brand);
      box-shadow: 0 0 0 3px var(--work-brand-soft); }
    .engine[data-tier="memory"] .dot { background: var(--work-warn); box-shadow: 0 0 0 3px var(--work-warn-soft); }
    .engine[data-tier="error"] .dot { background: var(--work-err); box-shadow: none; }

    .plot { padding: var(--work-space-3) var(--work-space-4) var(--work-space-4); position: relative; }
    .powered:empty { display: none; }
    /* when the powered tier (Observable Plot) has rendered into .powered, the floor
       SVG is declaratively hidden — no imperative show/hide race against Lit's
       shell re-render or the ResizeObserver. */
    .plot:has(.powered > *) svg { display: none; }
    .powered > * { width: 100%; }
    svg { display: block; width: 100%; height: auto; overflow: visible; }
    text { font-family: var(--work-font); fill: var(--work-fg-muted); }
    .axis-label { fill: var(--work-fg-muted); font-size: var(--work-text-xs); }
    .axis-line { stroke: var(--work-border-strong); stroke-width: 1; }
    .grid { stroke: var(--work-border); stroke-width: 1; }
    .mark { transition: opacity var(--work-dur) var(--work-ease); cursor: pointer; }
    .plot[data-hover] .mark:not([data-active]) { opacity: 0.32; }
    .bar-rect { rx: 3; }
    .line-path { fill: none; stroke-width: 2; stroke-linejoin: round; stroke-linecap: round; }
    .area-fill { opacity: 0.16; }
    .dot-mark { stroke: var(--work-surface); stroke-width: 1.5; }

    .legend { display: flex; flex-wrap: wrap; gap: var(--work-space-3);
      padding: 0 var(--work-space-4) var(--work-space-3); font-size: var(--work-text-sm); color: var(--work-fg-muted); }
    .legend .key { display: inline-flex; align-items: center; gap: var(--work-space-1); cursor: default; }
    .legend .swatch { width: 11px; height: 11px; border-radius: var(--work-radius-xs); }

    .tip { position: absolute; pointer-events: none; z-index: 3; opacity: 0;
      transform: translate(-50%, calc(-100% - 10px));
      background: var(--work-fg); color: var(--work-surface);
      font-family: var(--work-font-mono); font-size: var(--work-text-sm);
      padding: var(--work-space-1) var(--work-space-2); border-radius: var(--work-radius-sm);
      white-space: nowrap; box-shadow: var(--work-shadow); transition: opacity var(--work-dur) var(--work-ease); }
    .tip[data-show] { opacity: 1; }
    .tip .tk { color: var(--work-surface-soft); }

    .empty { padding: var(--work-space-5); text-align: center; color: var(--work-fg-muted); font-size: var(--work-text-sm); }
    .foot { padding: 0 var(--work-space-4) var(--work-space-3); font-size: var(--work-text-sm); color: var(--work-fg-subtle);
      font-family: var(--work-font-mono); }
    .foot .err { color: var(--work-err); }
  `;

  connectedCallback() {
    if (this._init == null) {
      this._init = true;
      this._engine = getEngine();
      this._result = null;
      this._tier = "memory";
      this._error = null;
      this._busy = true;
      this._series = [];            // [{ key, label, color }]
      this._captureSource();
      this._ro = new ResizeObserver(() => this._draw());
    }
    super.connectedCallback();
    this._ro.observe(this);
    this._load();
  }

  disconnectedCallback() {
    if (this._ro) this._ro.disconnect();
    super.disconnectedCallback();
  }

  // A named source: from="<work-query name>" is the canonical binding; src-name is
  // the equivalent register()-side name. Either names a source the engine resolves.
  _namedSource() { return this.attr("from") || this.attr("src-name"); }

  _captureSource() {
    this._srcName = this._namedSource();
    if (!this._srcName) {
      const rowsAttr = this.attr("rows");
      const csvAttr = this.attr("csv");
      if (!this._autoName) this._autoName = `work_chart_${++_autoId}`;
      this._srcName = this._autoName;
      if (rowsAttr) this._pendingSource = { json: rowsAttr };
      else if (csvAttr) this._pendingSource = { csv: csvAttr };
      else {
        const text = this.textContent.trim();
        if (text.startsWith("[")) this._pendingSource = { json: text };
        else if (text.includes(",")) this._pendingSource = { csv: text };
      }
    }
  }

  attributeChangedCallback(name, old, val) {
    super.attributeChangedCallback(name, old, val);
    if (!this._init) return;
    if (name === "rows" || name === "csv" || name === "src-name" || name === "from" || name === "query") {
      this._pendingSource = null;
      this._captureSource();
      this._load();
    } else {
      // re-layout / re-render from the cached result; no re-query needed
      this.requestUpdate();
    }
  }

  async _load() {
    // Single-flight: overlapping loads would let one load's register()
    // (DROP+CREATE) yank the table out from under another's in-flight query.
    if (this._loading) { this._loadAgain = true; return; }
    this._loading = true;
    do {
      this._loadAgain = false;
      this._busy = true; this._error = null; this.requestUpdate();
      try {
        if (this._pendingSource) await this._engine.register(this._srcName, this._pendingSource);
        else if (this._namedSource()) await this._engine.whenRegistered(this._srcName);
        await this._run();
      } catch (e) {
        this._error = String((e && e.message) || e);
        this._tier = "error";
      }
      this._busy = false;
      this.requestUpdate();
      this._emit("work-chart-ready", {
        type: this.variant("type"),
        columns: this._result?.columns || [],
        types: this._result?.types || [],
        engine: this._tier,
        series: this._series.map((s) => s.key),
        rowCount: this._result?.rowCount || 0,
      });
    } while (this._loadAgain);
    this._loading = false;
  }

  async _run() {
    // The aggregate/GROUP BY lives in the author's `query` (engine-computed). With
    // no query, default to SELECT * over the named source — the engine still
    // answers; the element never wrangles.
    const sql = this.attr("query") || `SELECT * FROM ${ident(this._srcName)}`;
    this._result = await this._engine.query(sql);
    this._tier = this._result.engine || this._engine.provider();
    this._emit("work-chart-query", { sql, rowCount: this._result.rowCount, engine: this._tier });
  }

  variant(name) { return resolveVariant(this, VARIANTS, name); }

  // The canonical LOGICAL model of the chart — series, data-point count, domain,
  // category labels — independent of which tier drew it. The parity gate uses this
  // off the FLOOR render as the oracle (the floor maps the engine result directly,
  // so it IS the ground truth for "what the data says"). Pure read of _layout().
  _logicalModel() {
    const lay = this._layout();
    if (!lay) return { seriesCount: 0, pointCount: 0, yMin: null, yMax: null, categories: [], seriesLabels: [] };
    let yMin = Infinity, yMax = -Infinity, pointCount = 0;
    for (const s of lay.series) for (const v of s.values) {
      if (v == null) continue;
      pointCount++;
      if (v < yMin) yMin = v;
      if (v > yMax) yMax = v;
    }
    return {
      type: lay.type,
      seriesCount: lay.series.length,
      pointCount,
      yMin: isFinite(yMin) ? yMin : null,
      yMax: isFinite(yMax) ? yMax : null,
      categories: lay.categories.map((c) => String(c)),
      seriesLabels: lay.series.map((s) => String(s.label)),
    };
  }

  // ── render (shell only; the SVG is drawn imperatively in _draw) ───────────────
  render() {
    const title = this.attr("title");
    const tierText = this._busy ? "querying…" :
      this._error ? "engine error" :
      this._tier === "runtime" ? "runtime DuckDB" :
      this._tier === "duckdb-wasm" ? "DuckDB-wasm" : "in-JS (offline)";
    const head = `
      <div class="head">
        ${title ? `<span class="title">${esc(title)}</span>` : ""}
        <span class="grow"></span>
        <span class="engine" data-tier="${this._error ? "error" : this._tier}"><span class="dot"></span>${esc(tierText)}</span>
      </div>`;
    const shell = `<div class="shell">
      ${head}
      <div class="plot"><div class="tip"></div><div class="powered" part="powered"></div><svg part="svg"></svg></div>
      <div class="legend"></div>
      <div class="foot">${this._error ? `<span class="err">${esc(this._error)}</span>` : ""}</div>
    </div>`;
    return html`${unsafeHTML(shell)}`;
  }

  // Lit lifecycle: the shell just (re)rendered — draw the SVG against the cached
  // result (base used to do this in an update() override; Lit's hook is updated()).
  updated() {
    if (this._result && !this._busy) this._draw();
    else this._draw(); // clears / shows empty as needed
  }

  // ── layout: map the WbQueryResult { columns, rows[][], types } to marks ───────
  _layout() {
    const r = this._result;
    if (!r || !r.columns.length || !r.rows.length) return null;
    const cols = r.columns;
    const idx = (name) => cols.indexOf(name);

    const type = this.variant("type");
    const fmt = this.attr("format");
    const xName = this.attr("x") || cols[0];
    const xj = idx(xName) >= 0 ? idx(xName) : 0;

    // y columns: explicit list, else the series-pivot column, else "all numeric
    // columns that are not x". Series are layout only — values come from rows[][].
    const seriesCol = this.attr("series");
    let yNames = (this.attr("y") || "").split(",").map((s) => s.trim()).filter(Boolean);

    let categories, series;
    const colorFor = (i) => PALETTE[i % PALETTE.length];

    if (seriesCol && yNames.length === 1) {
      // long → wide: distinct values of seriesCol become series, yNames[0] is the value
      const sj = idx(seriesCol), yj = idx(yNames[0]);
      const catSet = [], catPos = new Map();
      const keys = [], keyPos = new Map();
      for (const row of r.rows) {
        const c = row[xj];
        if (!catPos.has(c)) { catPos.set(c, catSet.length); catSet.push(c); }
        const k = row[sj];
        if (!keyPos.has(k)) { keyPos.set(k, keys.length); keys.push(k); }
      }
      categories = catSet;
      series = keys.map((k, i) => ({
        key: String(k), label: String(k), color: colorFor(i),
        values: new Array(catSet.length).fill(null),
      }));
      for (const row of r.rows) {
        const ci = catPos.get(row[xj]);
        const si = keyPos.get(row[sj]);
        series[si].values[ci] = toNum(row[yj]);
      }
    } else {
      if (!yNames.length) {
        // every numeric column except x
        yNames = cols.filter((c, j) => j !== xj && (r.types[j] === "number" || r.types[j] === "integer"));
        if (!yNames.length) yNames = cols.filter((_, j) => j !== xj).slice(0, 1);
      }
      categories = r.rows.map((row) => row[xj]);
      series = yNames.map((name, i) => ({
        key: name, label: prettify(name), color: colorFor(i),
        values: r.rows.map((row) => toNum(row[idx(name)])),
      }));
    }

    // x values for scatter are numeric; otherwise categorical/ordinal index
    const xNumeric = type === "scatter" && (r.types[xj] === "number" || r.types[xj] === "integer");
    const xVals = categories.map((c) => (xNumeric ? toNum(c) : c));

    this._series = series;
    return { type, fmt, xName, categories, xVals, xNumeric, series, rows: r.rows, xj };
  }

  // Which tier should draw? floor (zero-dep SVG) vs plot (Observable Plot).
  //   - attribute engine="floor" | "plot" forces it (the gate drives this)
  //   - window.__WB_CHART_ENGINE__ = "floor" | "plot" is the host opt-out
  //   - default "auto": prefer Plot when it loads, fall back to the floor.
  // Returns "floor" | "plot". A non-floor verdict still falls back to the floor
  // synchronously if Plot has not resolved yet (the floor never blocks on a CDN).
  _tierChoice() {
    const attr = this.attr("engine");
    if (attr === "floor" || attr === "plot") return attr;
    const host = typeof window !== "undefined" && window.__WB_CHART_ENGINE__;
    if (host === "floor" || host === "plot") return host;
    return "auto";
  }

  _draw() {
    const svg = this.shadowRoot && this.shadowRoot.querySelector("svg");
    const powered = this.shadowRoot && this.shadowRoot.querySelector(".powered");
    if (!svg) return;
    const lay = this._layout();
    const legendEl = this.shadowRoot.querySelector(".legend");
    if (!lay) {
      svg.innerHTML = "";
      svg.removeAttribute("viewBox");
      if (powered) powered.innerHTML = "";
      if (legendEl) legendEl.innerHTML = "";
      if (!this._busy && !this._error) {
        const plot = this.shadowRoot.querySelector(".plot");
        if (plot && !plot.querySelector(".empty")) {
          const e = document.createElement("div");
          e.className = "empty"; e.textContent = "No data.";
          plot.appendChild(e);
        }
      }
      return;
    }
    const plot = this.shadowRoot.querySelector(".plot");
    const oldEmpty = plot && plot.querySelector(".empty");
    if (oldEmpty) oldEmpty.remove();

    const choice = this._tierChoice();
    if (choice === "floor") return this._drawFloor(svg, powered, lay, legendEl);

    // powered path. If Plot has already resolved (cached on the instance), render
    // it SYNCHRONOUSLY this frame — no floor flash, no svg un-hide race on resize.
    // Otherwise draw the floor instantly (never a blank chart) and upgrade to Plot
    // once the lazy import lands.
    if (this._Plot && powered) {
      const ok = this._renderPoweredSync(svg, powered, lay, legendEl, this._Plot, choice === "plot");
      if (ok) return;
    }
    this._drawFloor(svg, powered, lay, legendEl);
    this._drawPowered(svg, powered, lay, legendEl, choice === "plot");
  }

  // Render the Plot figure into the powered host with an already-loaded Plot ns.
  // Returns true on success (svg hidden, figure shown); false to fall to floor.
  _renderPoweredSync(svg, powered, lay, legendEl, Plot, forced) {
    if (!this._result) return false;
    const tk = readTokens(this);
    const W = Math.max(320, this.getBoundingClientRect().width || 640);
    const H = HEIGHTS[this.variant("size")] || HEIGHTS.md;
    let fig;
    try {
      fig = renderPlot(Plot, lay, tk, {
        width: W, height: H, format: lay.fmt, legend: this.attr("legend", "auto"),
      });
    } catch (e) {
      if (forced) console.warn("work-chart: Plot render failed, keeping floor", e);
      return false;
    }
    powered.innerHTML = "";
    powered.appendChild(fig);
    // the floor SVG is hidden declaratively by CSS (.plot:has(.powered > *) svg);
    // clear its marks so it carries no stale render behind the figure.
    svg.innerHTML = "";
    svg.removeAttribute("viewBox");
    if (legendEl) legendEl.innerHTML = "";
    this._engineTier = "plot";
    this._wirePlotSelect(fig, lay);
    return true;
  }

  // The zero-dependency SVG floor (the original renderer). Hides the powered host.
  _drawFloor(svg, powered, lay, legendEl) {
    if (powered) powered.innerHTML = "";   // empty .powered → CSS shows the floor svg
    const H = HEIGHTS[this.variant("size")] || HEIGHTS.md;
    // viewBox-driven so the SVG scales fluidly; width:100% in CSS.
    const vbW = Math.max(320, this.getBoundingClientRect().width || 640);
    const vbH = H;
    if (lay.type === "pie") this._drawPie(svg, lay, vbW, vbH);
    else this._drawXY(svg, lay, vbW, vbH);
    this._drawLegend(legendEl, lay);
    this._wireHover(svg, lay);
    this._engineTier = "floor";
  }

  // The POWERED tier — Observable Plot, lazy-loaded. On success it replaces the
  // floor SVG with a Plot <figure> rendered from the SAME `lay` model, themed from
  // the live --work-* tokens. On failure (network-blocked / load error) it leaves
  // the floor in place (forced="plot" still degrades gracefully — the floor IS the
  // guaranteed render; the gate proves this).
  async _drawPowered(svg, powered, lay, legendEl, forced) {
    if (!powered) return;
    const token = (this._drawToken = (this._drawToken || 0) + 1);
    let Plot;
    try { Plot = await loadPlot(); }
    catch { return; /* floor already drawn — graceful degrade */ }
    if (token !== this._drawToken) return;      // a newer draw superseded this one
    this._Plot = Plot;                          // cache so later draws go sync
    const ok = this._renderPoweredSync(svg, powered, lay, legendEl, Plot, forced);
    if (ok) this._emit("work-chart-engine", { engine: "plot" });
  }

  // Forward Plot mark clicks to the SAME work-point-select contract as the floor.
  _wirePlotSelect(fig, lay) {
    const r = this._result;
    fig.querySelectorAll("[fill]").forEach((mark) => {
      mark.style.cursor = "pointer";
      mark.addEventListener("click", () => {
        // Plot bars/dots carry their datum index in document order; map back to
        // the layout. We approximate by reading the mark's __data__ when present.
        const d = mark.__data__;
        if (d == null) return;
        this._emit("work-point-select", { series: d.series, x: d.x, y: d.y, row: d, index: -1 });
      });
    });
  }

  _drawXY(svg, lay, W, H) {
    const { type, series, categories, xVals, xNumeric, fmt } = lay;
    const padL = 52, padR = 16, padT = 12, padB = 34;
    const plotW = W - padL - padR;
    const plotH = H - padT - padB;

    // y domain across all series; bars/areas baseline at 0
    let yMin = Infinity, yMax = -Infinity;
    for (const s of series) for (const v of s.values) {
      if (v == null) continue;
      if (v < yMin) yMin = v;
      if (v > yMax) yMax = v;
    }
    if (!isFinite(yMin)) { yMin = 0; yMax = 1; }
    if (type === "bar" || type === "area") yMin = Math.min(0, yMin);
    if (yMin === yMax) yMax = yMin + 1;
    const ticks = niceTicks(yMin, yMax, 5);
    yMin = ticks[0]; yMax = ticks[ticks.length - 1];
    const yScale = (v) => padT + plotH - ((v - yMin) / (yMax - yMin)) * plotH;

    // x scale
    const n = categories.length;
    let xScale, bandW;
    if (xNumeric) {
      let xmin = Infinity, xmax = -Infinity;
      for (const v of xVals) { if (v < xmin) xmin = v; if (v > xmax) xmax = v; }
      if (xmin === xmax) { xmin -= 0.5; xmax += 0.5; }
      xScale = (v) => padL + ((v - xmin) / (xmax - xmin)) * plotW;
      bandW = 0;
    } else {
      bandW = plotW / Math.max(1, n);
      xScale = (i) => padL + bandW * i + bandW / 2;   // category center
    }

    const parts = [];
    // gridlines + y axis ticks
    for (const t of ticks) {
      const y = yScale(t);
      parts.push(`<line class="grid" x1="${padL}" y1="${y.toFixed(1)}" x2="${(W - padR).toFixed(1)}" y2="${y.toFixed(1)}"/>`);
      parts.push(`<text class="axis-label" x="${padL - 8}" y="${(y + 3.5).toFixed(1)}" text-anchor="end">${esc(fmtVal(t, fmt))}</text>`);
    }
    // x baseline
    const y0 = yScale(Math.max(yMin, 0));
    parts.push(`<line class="axis-line" x1="${padL}" y1="${y0.toFixed(1)}" x2="${(W - padR).toFixed(1)}" y2="${y0.toFixed(1)}"/>`);

    // x category labels (thinned to avoid overlap)
    const step = Math.ceil(n / Math.max(1, Math.floor(plotW / 64)));
    if (!xNumeric) {
      categories.forEach((c, i) => {
        if (i % step !== 0) return;
        parts.push(`<text class="axis-label" x="${xScale(i).toFixed(1)}" y="${(H - padB + 18).toFixed(1)}" text-anchor="middle">${esc(trunc(c, 12))}</text>`);
      });
    } else {
      // numeric x ticks
      const xt = niceTicks(Math.min(...xVals), Math.max(...xVals), 5);
      for (const t of xt) parts.push(`<text class="axis-label" x="${xScale(t).toFixed(1)}" y="${(H - padB + 18).toFixed(1)}" text-anchor="middle">${esc(fmtVal(t, "num"))}</text>`);
    }

    // marks
    if (type === "bar") {
      const sCount = series.length;
      const groupPad = bandW * 0.18;
      const innerW = bandW - groupPad * 2;
      const barW = innerW / sCount;
      series.forEach((s, si) => {
        s.values.forEach((v, i) => {
          if (v == null) return;
          const x = padL + bandW * i + groupPad + barW * si;
          const yv = yScale(v);
          const h = Math.abs(y0 - yv);
          parts.push(`<rect class="mark bar-rect" data-s="${si}" data-i="${i}" x="${x.toFixed(1)}" y="${Math.min(y0, yv).toFixed(1)}" width="${Math.max(0.5, barW - 1.5).toFixed(1)}" height="${h.toFixed(1)}" fill="${s.color}"/>`);
        });
      });
    } else if (type === "line" || type === "area") {
      series.forEach((s, si) => {
        const pts = [];
        s.values.forEach((v, i) => {
          if (v == null) return;
          const x = xNumeric ? xScale(xVals[i]) : xScale(i);
          pts.push([x, yScale(v), i]);
        });
        if (!pts.length) return;
        const d = pts.map((p, k) => `${k ? "L" : "M"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
        if (type === "area") {
          const base = `${d} L${pts[pts.length - 1][0].toFixed(1)},${y0.toFixed(1)} L${pts[0][0].toFixed(1)},${y0.toFixed(1)} Z`;
          parts.push(`<path class="area-fill" d="${base}" fill="${s.color}"/>`);
        }
        parts.push(`<path class="line-path" d="${d}" stroke="${s.color}"/>`);
        // point handles for hover/select
        pts.forEach((p) => parts.push(`<circle class="mark dot-mark" data-s="${si}" data-i="${p[2]}" cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="3.5" fill="${s.color}"/>`));
      });
    } else if (type === "scatter") {
      series.forEach((s, si) => {
        s.values.forEach((v, i) => {
          if (v == null) return;
          const x = xNumeric ? xScale(xVals[i]) : xScale(i);
          parts.push(`<circle class="mark dot-mark" data-s="${si}" data-i="${i}" cx="${x.toFixed(1)}" cy="${yScale(v).toFixed(1)}" r="5" fill="${s.color}"/>`);
        });
      });
    }

    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.innerHTML = parts.join("");
  }

  _drawPie(svg, lay, W, H) {
    const { series, categories, fmt } = lay;
    // pie uses the FIRST series' values; slices = categories
    const s = series[0];
    const vals = s.values.map((v) => (v == null ? 0 : Math.max(0, v)));
    const total = vals.reduce((a, b) => a + b, 0) || 1;
    const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 14, r0 = R * 0.56;
    const parts = [];
    let a0 = -Math.PI / 2;
    // rebuild "series" as one-slice-per-category for legend + hover semantics
    const slices = [];
    categories.forEach((c, i) => {
      const frac = vals[i] / total;
      if (frac <= 0) { slices.push({ label: String(c), color: PALETTE[i % PALETTE.length], value: vals[i], pct: 0 }); return; }
      const a1 = a0 + frac * Math.PI * 2;
      const large = a1 - a0 > Math.PI ? 1 : 0;
      const p = (ang, rad) => `${(cx + Math.cos(ang) * rad).toFixed(1)},${(cy + Math.sin(ang) * rad).toFixed(1)}`;
      const d = `M${p(a0, R)} A${R},${R} 0 ${large} 1 ${p(a1, R)} L${p(a1, r0)} A${r0},${r0} 0 ${large} 0 ${p(a0, r0)} Z`;
      const color = PALETTE[i % PALETTE.length];
      parts.push(`<path class="mark" data-s="0" data-i="${i}" d="${d}" fill="${color}"/>`);
      slices.push({ label: String(c), color, value: vals[i], pct: frac });
      a0 = a1;
    });
    // center total
    parts.push(`<text x="${cx}" y="${cy - 2}" text-anchor="middle" style="fill:var(--work-fg);font-weight:600;font-size:18px">${esc(fmtVal(total, fmt))}</text>`);
    parts.push(`<text x="${cx}" y="${cy + 16}" text-anchor="middle" class="axis-label" style="font-family:var(--work-font-mono)">total</text>`);
    svg.setAttribute("viewBox", `0 0 ${W} ${H}`);
    svg.innerHTML = parts.join("");
    lay._slices = slices;   // for legend + hover
  }

  _drawLegend(el, lay) {
    if (!el) return;
    const mode = this.attr("legend", "auto");
    const keys = lay.type === "pie"
      ? (lay._slices || []).map((s) => ({ label: trunc(s.label, 18), color: s.color }))
      : lay.series.map((s) => ({ label: trunc(s.label, 18), color: s.color }));
    if (mode === "off" || keys.length <= 1) { el.innerHTML = ""; return; }
    el.innerHTML = keys.map((k) =>
      `<span class="key"><span class="swatch" style="background:${k.color}"></span>${esc(k.label)}</span>`).join("");
  }

  _wireHover(svg, lay) {
    const tip = this.shadowRoot.querySelector(".tip");
    const plot = this.shadowRoot.querySelector(".plot");
    const fmt = lay.fmt;
    const r = this._result;
    const marks = svg.querySelectorAll(".mark");
    const show = (mark, ev) => {
      const si = +mark.getAttribute("data-s");
      const i = +mark.getAttribute("data-i");
      marks.forEach((m) => m.removeAttribute("data-active"));
      mark.setAttribute("data-active", "");
      plot.setAttribute("data-hover", "");
      let label, value;
      if (lay.type === "pie") {
        const sl = lay._slices[i];
        label = sl.label; value = `${fmtVal(sl.value, fmt)} · ${(sl.pct * 100).toFixed(1)}%`;
      } else {
        const s = lay.series[si];
        label = `${esc(s.label)} · ${esc(trunc(lay.categories[i], 18))}`;
        value = fmtVal(s.values[i], fmt);
      }
      tip.innerHTML = `<span class="tk">${esc(label)}</span> ${esc(value)}`;
      const box = plot.getBoundingClientRect();
      tip.style.left = (ev.clientX - box.left) + "px";
      tip.style.top = (ev.clientY - box.top) + "px";
      tip.setAttribute("data-show", "");
    };
    const hide = () => {
      tip.removeAttribute("data-show");
      plot.removeAttribute("data-hover");
      marks.forEach((m) => m.removeAttribute("data-active"));
    };
    marks.forEach((mark) => {
      mark.addEventListener("mousemove", (ev) => show(mark, ev));
      mark.addEventListener("mouseleave", hide);
      mark.addEventListener("click", () => {
        const si = +mark.getAttribute("data-s");
        const i = +mark.getAttribute("data-i");
        const rowObj = {};
        if (r) r.columns.forEach((c, j) => (rowObj[c] = r.rows[i] ? r.rows[i][j] : null));
        const s = lay.series[si];
        this._emit("work-point-select", {
          series: lay.type === "pie" ? lay._slices[i].label : s.key,
          x: lay.categories[i],
          y: lay.type === "pie" ? lay._slices[i].value : s.values[i],
          row: rowObj, index: i,
        });
      });
    });
  }

  _emit(name, detail) {
    this.dispatchEvent(new CustomEvent(name, { detail, bubbles: true, composed: true }));
  }
}

// ── helpers (token-unaware) ──────────────────────────────────────────────────
function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }
function toNum(v) { if (v == null || v === "") return null; const n = Number(v); return Number.isNaN(n) ? null : n; }
function esc(s) {
  return String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
}
function prettify(f) { return String(f).replace(/[_-]+/g, " ").replace(/\b\w/g, (c) => c.toUpperCase()); }
function trunc(s, n) { s = String(s ?? ""); return s.length > n ? s.slice(0, n - 1) + "…" : s; }
function fmtVal(v, format) {
  if (v == null) return "";
  const n = Number(v);
  if (format === "usd") return "$" + abbrev(n);
  if (format === "pct") return (n * (Math.abs(n) <= 1 ? 100 : 1)).toFixed(1) + "%";
  if (format === "num") return abbrev(n);
  return Number.isInteger(n) ? n.toLocaleString() : abbrev(n);
}
function abbrev(n) {
  const a = Math.abs(n);
  if (a >= 1e9) return (n / 1e9).toFixed(1).replace(/\.0$/, "") + "B";
  if (a >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
  if (a >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, "") + "k";
  return Number.isInteger(n) ? n.toLocaleString() : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
}
// "Nice" axis ticks (1/2/5 × 10^k), inclusive of rounded min/max.
function niceTicks(min, max, count) {
  if (min === max) { min -= 1; max += 1; }
  const span = niceNum(max - min, false);
  const stepc = niceNum(span / Math.max(1, count - 1), true);
  const niceMin = Math.floor(min / stepc) * stepc;
  const niceMax = Math.ceil(max / stepc) * stepc;
  const out = [];
  for (let v = niceMin; v <= niceMax + stepc * 0.5; v += stepc) out.push(+v.toFixed(10));
  return out;
}
function niceNum(range, round) {
  const exp = Math.floor(Math.log10(range || 1));
  const frac = (range || 1) / Math.pow(10, exp);
  let nf;
  if (round) nf = frac < 1.5 ? 1 : frac < 3 ? 2 : frac < 7 ? 5 : 10;
  else nf = frac <= 1 ? 1 : frac <= 2 ? 2 : frac <= 5 ? 5 : 10;
  return nf * Math.pow(10, exp);
}

define("work-chart", WbChart);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP), or `kernel` (oql.wasm) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}

// workponents · data — THE shared query/result contract.
//
// This is the single data interface every data surface consumes:
// `tables`, `data-viz`, `maps`, `records`, and `search` all talk to ONE engine
// through this shape. It is framework-agnostic, zero-dependency, and TOKEN-UNAWARE
// (pure data — no CSS, no DOM). An element imports `getEngine()` from ./engine.js,
// registers its source once, and runs queries; the element owns render + theme.
//
// The engine is SQLite, resolved by the Host per context: the workbook's native
// SQLite VFS over the runtime (Dock `vfs-query`), in-page sqlite-wasm when static,
// or the in-JS subset floor. One SQL dialect everywhere — write SQLite SQL.
//
// ─────────────────────────────────────────────────────────────────────────────
// Result shape — every query (runtime VFS, in-page sqlite-wasm, or the in-JS
// floor) returns EXACTLY this. Every surface must code against this and nothing
// else:
//
//   /** @typedef {Object} WbQueryResult
//    *  @property {string[]}    columns  ordered column names
//    *  @property {any[][]}     rows     row-major; rows[i][j] is column j of row i
//    *  @property {WbColType[]} types    per-column logical type (columns.length)
//    *  @property {number}      rowCount rows.length (convenience)
//    *  @property {string}      [engine] which tier answered: runtime|sqlite-wasm|memory
//    *  @property {string}      [sql]    the SQL actually executed (debug)
//    */
//
//   WbColType ∈ "number" | "integer" | "string" | "boolean" | "date" | "json"
//
// Engine surface (engine.js implements this; every surface reuses it verbatim):
//
//   query(sql: string, params?: any[]) -> Promise<WbQueryResult>
//   register(name: string, source: WbSource) -> Promise<void>   // makes a table
//   whenRegistered(name: string) -> Promise<void>  // await before querying it
//   available() -> boolean      // is a real SQLite tier reachable (vs the floor)
//   writable() -> boolean       // are writes durable (runtime VFS) vs local/none
//   provider() -> string        // "runtime" | "sqlite-wasm" | "memory"
//
// Source registration — "a workbook's data IS its source" (for INLINE data; a
// real workbook's tables already live in its SQLite VFS, no registration). One of:
//
//   { rows: object[] }                         inline array of row objects
//   { columns: string[], rows: any[][] }       columnar inline
//   { csv: string }                            CSV text (header row)
//   { json: string | object[] }                JSON text or parsed array
//   { url: string, format?: "csv"|"json" }     fetched (browser/runtime)
//
// `params` use positional `?` placeholders (SQLite style). All tiers bind the same.
// ─────────────────────────────────────────────────────────────────────────────

/** Normalize any WbSource into { columns, rows(object[]) } for registration. */
export function normalizeSource(src) {
  if (!src || typeof src !== "object") throw new Error("wb-data: source must be an object");
  if (Array.isArray(src.rows) && src.columns) {
    // columnar inline → objects
    const cols = src.columns;
    return { columns: cols, rows: src.rows.map((r) => objFromRow(cols, r)) };
  }
  if (Array.isArray(src.rows)) {
    const cols = inferColumns(src.rows);
    return { columns: cols, rows: src.rows };
  }
  if (typeof src.csv === "string") return parseCsv(src.csv);
  if (src.json != null) {
    const arr = typeof src.json === "string" ? JSON.parse(src.json) : src.json;
    if (!Array.isArray(arr)) throw new Error("wb-data: json source must be an array of rows");
    return { columns: inferColumns(arr), rows: arr };
  }
  throw new Error("wb-data: unsupported source (need rows|columns+rows|csv|json|url|arrow)");
}

function objFromRow(cols, row) {
  if (Array.isArray(row)) {
    const o = {};
    cols.forEach((c, i) => (o[c] = row[i]));
    return o;
  }
  return row;
}

function inferColumns(rows) {
  const seen = new Set();
  const cols = [];
  for (const r of rows) for (const k of Object.keys(r)) if (!seen.has(k)) { seen.add(k); cols.push(k); }
  return cols;
}

/** Minimal RFC-4180-ish CSV parse (quotes, escaped quotes, commas, newlines). */
export function parseCsv(text) {
  const rows = [];
  let field = "", row = [], inQ = false;
  const t = text.replace(/\r\n?/g, "\n");
  for (let i = 0; i < t.length; i++) {
    const c = t[i];
    if (inQ) {
      if (c === '"') { if (t[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else if (c === '"') inQ = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n") { row.push(field); rows.push(row); field = ""; row = []; }
    else field += c;
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  const filtered = rows.filter((r) => r.length > 1 || (r.length === 1 && r[0] !== ""));
  if (!filtered.length) return { columns: [], rows: [] };
  const columns = filtered[0].map((h) => h.trim());
  const out = filtered.slice(1).map((r) => {
    const o = {};
    columns.forEach((col, i) => (o[col] = coerce(r[i])));
    return o;
  });
  return { columns, rows: out };
}

/** Coerce a CSV/string cell to number/boolean where it is unambiguous. */
export function coerce(v) {
  if (v == null) return null;
  const s = String(v).trim();
  if (s === "") return null;
  if (s === "true") return true;
  if (s === "false") return false;
  if (/^-?\d+$/.test(s)) return parseInt(s, 10);
  if (/^-?\d*\.\d+$/.test(s)) return parseFloat(s);
  return s;
}

/** Infer a WbColType from a sample of column values. */
export function inferType(values) {
  let n = 0, allInt = true, num = 0, bool = 0, total = 0;
  for (const v of values) {
    if (v == null) continue;
    total++;
    if (typeof v === "boolean") { bool++; continue; }
    if (typeof v === "number") { num++; if (!Number.isInteger(v)) allInt = false; continue; }
    n++;
  }
  if (total === 0) return "string";
  if (bool === total) return "boolean";
  if (num === total) return allInt ? "integer" : "number";
  return "string";
}

/** Build a WbQueryResult (columns/rows array-of-array/types) from row objects. */
export function resultFromObjects(rowObjs, columns, engine, sql) {
  const cols = columns || inferColumns(rowObjs);
  const rows = rowObjs.map((o) => cols.map((c) => o[c] ?? null));
  const types = cols.map((c, j) => inferType(rows.map((r) => r[j])));
  return { columns: cols, rows, types, rowCount: rows.length, engine, sql };
}

// workponents · data — the shared SQLite seam, behind the Host/Dock membrane.
//
// ONE engine, every data surface: `tables`, `data-viz`, `maps`, `records`, and
// `search` all import `getEngine()` and consume the contract in ./contract.js.
// A component NEVER picks where SQL runs — the Host resolves the tier by context
// (the platform-model `local | runtime` seam):
//
//   • runtime — a Workbooks runtime/nexus is connected. SQL routes over the Dock
//     to the workbook's native SQLite VFS (`exqlite`, server-side) via the
//     tenant query route. Data stays OUT of the client; writes are durable
//     (Litestream). This is "the unbundling" — the SQLite is docked out to the
//     nexus so it can be edited live.
//
//   • sqlite-wasm — no runtime. Real SQLite in the page (./sqlite-wasm.js): the
//     full dialect, byte-compatible with the runtime's `exqlite`. ~1MB, lazily
//     loaded once. "The SQLite layer in the workbook itself" — and, ahead, the
//     engine that opens a static workbook's hydrated embedded VFS (the single-HTML
//     format: VFS embedded as a compressed blob, hydrated via DecompressionStream).
//
//   • memory — last-resort floor (./memory-sql.js): the zero-dep in-JS SQL subset,
//     used only if sqlite-wasm can't load (offline, no CDN/self-host). It is a
//     SUBSET — not real SQLite — so sqlite-wasm is preferred whenever reachable.
//
// One SQLite dialect everywhere — native `exqlite` (runtime) and sqlite-wasm
// (browser) are two builds of the same engine, and a workbook's `.sqlite` is
// byte-portable between them. (DuckDB-wasm was removed: 34MB, a divergent dialect,
// and redundant — the workbook already ships SQLite.)

import { getHost } from "../core/host.js";
import { normalizeSource, resultFromObjects } from "./contract.js";
import { WasmSqlite, bootSqlite } from "./sqlite-wasm.js";
import { MemorySql } from "./memory-sql.js";

let _engine = null;

/** The shared engine singleton. Lazy, idempotent — call from any element. */
export function getEngine() {
  if (!_engine) _engine = new WbDataEngine();
  return _engine;
}

export class WbDataEngine {
  constructor() {
    this._host = getHost();
    this._sqlite = new WasmSqlite();  // real in-page SQLite (the local tier)
    this._memory = new MemorySql();   // zero-dep subset (load-failure floor only)
    this._sources = new Map();        // name -> normalized {columns, rows}
    this._provider = null;            // resolved on first use
    this._initPromise = null;
    this._regWaiters = new Map();     // name -> [resolve, ...] awaiting registration
    this._inflightRegs = new Set();   // register() promises still settling
    // Runtime SQL-over-VFS route (tenant SQLite via the Dock). `{tenant}` is
    // filled from the Host. Override per deploy if a runtime exposes another path.
    this.vfsQueryPath = "/api/library/{tenant}/query";
  }

  /**
   * Resolve once `name` is registered (and live on the active provider). Returns
   * immediately if it already is. Lets a declarative element with `src-name`
   * upgrade BEFORE the page calls register() without racing an unknown table —
   * the one ordering hazard shared by every surface.
   */
  whenRegistered(name) {
    if (this._sources.has(name)) return Promise.resolve();
    return new Promise((resolve) => {
      const arr = this._regWaiters.get(name) || [];
      arr.push(resolve);
      this._regWaiters.set(name, arr);
    });
  }

  /** Which tier answers: "runtime" (native VFS) | "sqlite-wasm" (local) | "memory". */
  provider() { return this._provider || (this._runtimeReady() ? "runtime" : "sqlite-wasm"); }

  /** Is a real SQLite engine reachable (runtime VFS or in-page sqlite-wasm)? */
  available() { return this._runtimeReady() || this._provider === "sqlite-wasm"; }

  /** Are writes durable (runtime/nexus `exqlite`) vs local/ephemeral or none? */
  writable() { return this._runtimeReady(); }

  _runtimeReady() {
    return this._host.available("vfs") || (this._host.runtimeUrl != null);
  }

  /** Register a named source so SQL can `FROM <name>`. Idempotent per name. */
  register(name, source) {
    // Track the in-flight promise so a query that references this table before
    // it lands (an element querying a table a SIBLING registers — no src-name
    // declared) can await it and retry, instead of failing "no such table".
    const p = this._doRegister(name, source);
    this._inflightRegs.add(p);
    p.finally(() => this._inflightRegs.delete(p));
    return p;
  }

  async _doRegister(name, source) {
    const norm = normalizeSource(source);
    this._sources.set(name, norm);
    // Seed the floor too, so a sqlite-wasm load failure still answers.
    this._memory.register(name, norm);
    await this._ensureProvider();
    if (this._provider === "runtime") {
      // Inline data pushed into a docked workbook (best-effort). Real workbook
      // tables already live in the VFS and need no registration.
      try {
        await this._host.request(this._regPath(), { body: { name, columns: norm.columns, rows: norm.rows } });
      } catch { /* runtime ingest best-effort; the floor still answers */ }
    } else if (this._provider === "sqlite-wasm") {
      await this._sqlite.register(name, norm);
    }
    // Now queryable on the active provider — release anyone awaiting this source.
    const waiters = this._regWaiters.get(name);
    if (waiters) { this._regWaiters.delete(name); for (const r of waiters) r(); }
  }

  /** query(sql, params?) -> Promise<WbQueryResult>. Every surface's one call. */
  async query(sql, params = []) {
    await this._ensureProvider();
    if (this._provider === "runtime") {
      try {
        const res = await this._host.request(this._queryPath(), { body: { sql, params } });
        const shaped = shapeRuntime(res, sql);
        if (shaped) return shaped;
      } catch { /* fall through to the local engine */ }
    }
    if (this._provider === "sqlite-wasm") {
      try {
        return await this._sqlite.query(sql, params);
      } catch (e) {
        // The table may simply not be registered YET (a sibling's register() is
        // mid-flight). Wait for pending registrations, then retry once.
        if (/no such table/i.test(String(e && e.message || e)) && this._inflightRegs.size) {
          await Promise.allSettled([...this._inflightRegs]);
          return this._sqlite.query(sql, params);
        }
        throw e;
      }
    }
    // Last-resort floor — the zero-dep in-JS subset (sqlite-wasm unavailable).
    return this._memory.query(sql, params);
  }

  // ── provider resolution ────────────────────────────────────────────────────
  async _ensureProvider() {
    if (this._provider) return;
    if (this._initPromise) return this._initPromise;
    // Runtime/nexus SQLite VFS when connected; else real in-page sqlite-wasm;
    // the in-JS subset only if sqlite-wasm can't load (offline, no CDN/self-host).
    this._initPromise = (async () => {
      if (this._runtimeReady()) { this._provider = "runtime"; return; }
      try {
        await bootSqlite();
        this._provider = "sqlite-wasm";
        // No re-registration here: every source arrives via register(), which
        // registers into the resolved provider after awaiting this boot. Looping
        // here too would double-register the same table concurrently (DROP/CREATE
        // racing a sibling's DDL) → transient "no such table".
      } catch {
        this._provider = "memory";
      }
    })();
    return this._initPromise;
  }

  _queryPath() {
    return this.vfsQueryPath.replace("{tenant}", encodeURIComponent(this._host.tenant || "local"));
  }
  _regPath() {
    return this._queryPath().replace(/\/query$/, "/register");
  }
}

/**
 * Shape a runtime SQL response into a WbQueryResult. Tolerant of the row shapes a
 * runtime may return ({columns, rows[][]} columnar, or an array of row-objects).
 * Returns null when unrecognized so query() falls back to the local floor.
 */
function shapeRuntime(res, sql) {
  if (!res) return null;
  if (Array.isArray(res)) {
    return resultFromObjects(res, res.length ? Object.keys(res[0]) : [], "runtime", sql);
  }
  if (Array.isArray(res.rows) && Array.isArray(res.columns)) {
    const types = res.types || res.columns.map(() => "string");
    return { columns: res.columns, rows: res.rows, types, rowCount: res.rows.length, engine: "runtime", sql };
  }
  if (Array.isArray(res.rows)) {
    const cols = res.columns || (res.rows.length ? Object.keys(res.rows[0]) : []);
    return resultFromObjects(res.rows, cols, "runtime", sql);
  }
  return null;
}

// workponents · data — the shared in-WASM data layer for the DuckDB trio.
//
// ONE engine, three surfaces. `tables`, `data-viz`, and `maps` all import from
// here and code against the contract in ./contract.js. Framework-agnostic,
// zero-dependency, token-unaware (pure data — no DOM, no CSS).
//
//   import { getEngine } from "../../data/index.js";
//   const db = getEngine();
//   await db.register("orders", { csv: "...." });        // a workbook's data IS its source
//   const res = await db.query("SELECT region, sum(rev) AS rev FROM orders GROUP BY region");
//   // res = { columns, rows (array-of-array), types, rowCount, engine }
//
// data-viz / maps consume the SAME shape: a chart reads res.rows[i][j] by
// res.columns; a geo-query reads lat/lon columns off the same result. Register
// once, query from every surface on the page (shared connection).
export { getEngine, WbDataEngine } from "./engine.js";
export {
  normalizeSource, parseCsv, coerce, inferType, resultFromObjects,
} from "./contract.js";
export { MemorySql } from "./memory-sql.js";

// workponents · data — the in-JS fallback engine (zero-dep, offline).
//
// A small SQL-subset interpreter so the surfaces compute REAL sort/filter/aggregate
// IN an engine even with no runtime tier AND no network (CDN blocked). It is the
// LAST RESORT behind ./engine.js — when the runtime VFS (Host) or in-page
// sqlite-wasm is reachable, real SQLite answers instead and this is never touched.
// It is a SUBSET (no CAST, joins, window fns) — not real SQLite; prefer the tiers.
//
// Supported (one flat table per query, the basic grid/chart/geo-query needs):
//   SELECT <proj> FROM <table>
//     [WHERE <cond> [AND/OR <cond>]...]
//     [GROUP BY <col>[, <col>]...]
//     [ORDER BY <col|alias> [ASC|DESC]][, ...]
//     [LIMIT n [OFFSET m]]
//   proj: *, col, col AS alias, AGG(col) [AS alias], COUNT(*)
//   agg:  COUNT | SUM | AVG | MIN | MAX
//   cond: col OP value   OP ∈ = != <> < <= > >= LIKE   value: number|'str'|?
//   ? params bind positionally (SQLite style).
//
// Deliberately small. For anything beyond this, a real engine is required — the
// element degrades by surfacing the engine name so authors know which tier ran.

import { resultFromObjects } from "./contract.js";

const AGG_RE = /^(count|sum|avg|min|max)\s*\(\s*(\*|[\w."]+)\s*\)$/i;

export class MemorySql {
  constructor() {
    /** @type {Map<string,{columns:string[],rows:object[]}>} */
    this.tables = new Map();
  }

  register(name, normalized) {
    this.tables.set(name, normalized);
  }

  /** query(sql, params?) -> WbQueryResult */
  query(sql, params = []) {
    const q = parse(sql);
    const tbl = this.tables.get(q.from);
    if (!tbl) throw new Error(`wb-data(memory): unknown table "${q.from}"`);
    let rows = tbl.rows.slice();
    const binds = params.slice();

    // WHERE
    if (q.where.length) {
      rows = rows.filter((r) => evalWhere(r, q.where, binds.slice()));
    }

    let out;
    const hasAgg = q.select.some((s) => s.agg);
    if (q.groupBy.length || hasAgg) {
      out = aggregate(rows, q);
    } else {
      out = rows.map((r) => projectRow(r, q.select, tbl.columns));
    }

    // ORDER BY (by output alias/name)
    for (let i = q.orderBy.length - 1; i >= 0; i--) {
      const { key, dir } = q.orderBy[i];
      out.sort((a, b) => cmp(a[key], b[key]) * (dir === "desc" ? -1 : 1));
    }

    // LIMIT / OFFSET
    if (q.offset) out = out.slice(q.offset);
    if (q.limit != null) out = out.slice(0, q.limit);

    const columns = q.star ? (out[0] ? Object.keys(out[0]) : tbl.columns) : q.select.map((s) => s.alias);
    return resultFromObjects(out, columns, "memory", sql);
  }
}

function projectRow(r, select, allCols) {
  const o = {};
  for (const s of select) {
    if (s.star) { for (const c of allCols) o[c] = r[c]; continue; }
    o[s.alias] = r[s.col];
  }
  return o;
}

function aggregate(rows, q) {
  const groupCols = q.groupBy;
  const groups = new Map();
  for (const r of rows) {
    const key = groupCols.map((c) => r[c]).join("");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(r);
  }
  if (!groups.size && !groupCols.length) groups.set("", []); // global agg over empty set
  const out = [];
  for (const bucket of groups.values()) {
    const o = {};
    for (const s of q.select) {
      if (s.star && !s.agg) { for (const c of groupCols) o[c] = bucket[0]?.[c]; continue; }
      if (s.agg) o[s.alias] = applyAgg(s.agg, s.col, bucket);
      else o[s.alias] = bucket[0]?.[s.col] ?? null; // grouping column
    }
    out.push(o);
  }
  return out;
}

function applyAgg(agg, col, bucket) {
  if (agg === "count") return col === "*" ? bucket.length : bucket.filter((r) => r[col] != null).length;
  const nums = bucket.map((r) => Number(r[col])).filter((n) => !Number.isNaN(n));
  if (!nums.length) return null;
  if (agg === "sum") return nums.reduce((a, b) => a + b, 0);
  if (agg === "avg") return nums.reduce((a, b) => a + b, 0) / nums.length;
  if (agg === "min") return Math.min(...nums);
  if (agg === "max") return Math.max(...nums);
  return null;
}

function cmp(a, b) {
  if (a == null && b == null) return 0;
  if (a == null) return -1;
  if (b == null) return 1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  return String(a).localeCompare(String(b), undefined, { numeric: true });
}

function evalWhere(row, clauses, binds) {
  // clauses: [cond, {bool}, cond, ...] — left-to-right, AND/OR (no precedence/parens)
  let acc = null, op = "and";
  for (const node of clauses) {
    if (node.bool) { op = node.bool; continue; }
    const v = testCond(row, node, binds);
    acc = acc == null ? v : op === "and" ? acc && v : acc || v;
  }
  return acc == null ? true : acc;
}

function testCond(row, c, binds) {
  const lhs = row[c.col];
  const rhs = c.param ? binds.shift() : c.value;
  switch (c.op) {
    case "=": return looseEq(lhs, rhs);
    case "!=": case "<>": return !looseEq(lhs, rhs);
    case "<": return num(lhs) < num(rhs);
    case "<=": return num(lhs) <= num(rhs);
    case ">": return num(lhs) > num(rhs);
    case ">=": return num(lhs) >= num(rhs);
    case "like": return likeMatch(String(lhs ?? ""), String(rhs ?? ""));
    default: return false;
  }
}

function looseEq(a, b) {
  if (typeof a === "number" || typeof b === "number") return num(a) === num(b);
  return String(a) === String(b);
}
function num(v) { const n = Number(v); return Number.isNaN(n) ? v : n; }
function likeMatch(s, pat) {
  const re = new RegExp("^" + pat.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/%/g, ".*").replace(/_/g, ".") + "$", "i");
  return re.test(s);
}

// ── parser ───────────────────────────────────────────────────────────────────
function parse(sql) {
  const s = sql.trim().replace(/;$/, "");
  const m = /^select\s+(.+?)\s+from\s+([\w."]+)(.*)$/is.exec(s);
  if (!m) throw new Error("wb-data(memory): only SELECT … FROM … is supported");
  const projRaw = m[1], from = unquote(m[2]);
  let rest = m[3] || "";

  const where = [], groupBy = [], orderBy = [];
  let limit = null, offset = 0;

  const limitM = /\blimit\s+(\d+)(?:\s+offset\s+(\d+))?/i.exec(rest);
  if (limitM) { limit = +limitM[1]; offset = limitM[2] ? +limitM[2] : 0; rest = rest.replace(limitM[0], ""); }
  const offM = /\boffset\s+(\d+)/i.exec(rest);
  if (offM) { offset = +offM[1]; rest = rest.replace(offM[0], ""); }

  const orderM = /\border\s+by\s+(.+?)(?=\bgroup\s+by\b|$)/is.exec(rest);
  if (orderM) {
    rest = rest.replace(orderM[0], "");
    for (const part of orderM[1].split(",")) {
      const [, key, dir] = /^\s*([\w."]+)\s*(asc|desc)?\s*$/i.exec(part) || [];
      if (key) orderBy.push({ key: unquote(key), dir: (dir || "asc").toLowerCase() });
    }
  }
  const groupM = /\bgroup\s+by\s+(.+?)(?=\border\s+by\b|$)/is.exec(rest);
  if (groupM) {
    rest = rest.replace(groupM[0], "");
    for (const p of groupM[1].split(",")) groupBy.push(unquote(p.trim()));
  }
  const whereM = /\bwhere\s+(.+)$/is.exec(rest);
  if (whereM) parseWhere(whereM[1].trim(), where);

  const select = [];
  let star = false;
  for (const raw of splitTop(projRaw)) {
    const item = raw.trim();
    if (item === "*") { select.push({ star: true }); star = true; continue; }
    const asM = /\s+as\s+([\w]+)\s*$/i.exec(item);
    const alias = asM ? asM[1] : null;
    const expr = asM ? item.slice(0, asM.index).trim() : item;
    const aggM = AGG_RE.exec(expr);
    if (aggM) {
      const agg = aggM[1].toLowerCase();
      const col = aggM[2] === "*" ? "*" : unquote(aggM[2]);
      select.push({ agg, col, alias: alias || `${agg}_${col === "*" ? "all" : col}` });
    } else {
      const col = unquote(expr);
      select.push({ col, alias: alias || col });
    }
  }
  return { select, star, from, where, groupBy, orderBy, limit, offset };
}

function parseWhere(str, out) {
  // split on top-level AND/OR (no parens support — flat list)
  const parts = str.split(/\s+(and|or)\s+/i);
  for (let i = 0; i < parts.length; i++) {
    if (i % 2 === 1) { out.push({ bool: parts[i].toLowerCase() }); continue; }
    // accept the floor's `CAST(col AS TYPE)` coercion (used by work-search/-command
    // so non-string columns LIKE-match) — the memory tier is the floor's own offline
    // engine, so it must run the floor's own query. Reduce the cast to the column;
    // the JS comparison is type-agnostic (String() coerces), so the cast is a no-op.
    const cast = /^\s*CAST\s*\(\s*([\w."]+)\s+AS\s+\w+\s*\)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    const m = cast || /^\s*([\w."]+)\s*(<=|>=|<>|!=|=|<|>|like)\s*(.+?)\s*$/i.exec(parts[i]);
    if (!m) throw new Error(`wb-data(memory): bad WHERE clause "${parts[i]}"`);
    const col = unquote(m[1]), op = m[2].toLowerCase();
    let value = m[3].trim(), param = false;
    if (value === "?") param = true;
    else if (/^'.*'$/.test(value)) value = value.slice(1, -1).replace(/''/g, "'");
    else if (/^-?\d*\.?\d+$/.test(value)) value = parseFloat(value);
    out.push({ col, op, value, param });
  }
}

function splitTop(s) {
  // split on commas not inside parentheses
  const out = []; let depth = 0, cur = "";
  for (const c of s) {
    if (c === "(") depth++;
    else if (c === ")") depth--;
    if (c === "," && depth === 0) { out.push(cur); cur = ""; } else cur += c;
  }
  if (cur.trim()) out.push(cur);
  return out;
}

function unquote(s) { return String(s).trim().replace(/^"(.*)"$/, "$1"); }

// workponents · data — the browser-local SQLite tier (sqlite-wasm).
//
// Real SQLite, in the page: the full dialect, byte-compatible with the runtime's
// native `exqlite` VFS. This is "the SQLite layer in the workbook itself" for the
// static / no-runtime case — and, ahead, the engine that opens a workbook's
// hydrated embedded VFS (the single-HTML format). ~1MB, lazily loaded once.
//
// Override the asset base via `window.__WB_SQLITE_WASM__` (a base URL ending in
// `/`) to self-host instead of the CDN — e.g. ship the wasm with the workbook.
import { inferType } from "./contract.js";

const DEFAULT_BASE = "https://cdn.jsdelivr.net/npm/@sqlite.org/sqlite-wasm@3.50.1-build1/";
let _boot = null;

/** Boot sqlite-wasm once (idempotent). Resolves { sqlite3, db } (in-memory db). */
export function bootSqlite() {
  if (_boot) return _boot;
  _boot = (async () => {
    if (typeof window === "undefined") throw new Error("sqlite-wasm needs a browser");
    const base = window.__WB_SQLITE_WASM__ || DEFAULT_BASE;
    const mod = await import(/* @vite-ignore */ base + "index.mjs");
    const sqlite3 = await mod.default({ locateFile: (f) => base + "sqlite-wasm/jswasm/" + f });
    return { sqlite3, db: new sqlite3.oo1.DB(":memory:", "c") };
  })();
  return _boot;
}

/** A WbDataEngine tier backed by real in-page SQLite. Same contract as the floor. */
export class WasmSqlite {
  /** Register a normalized source ({columns, rows: object[]}) as a table. */
  async register(name, norm) {
    const { db } = await bootSqlite();
    const cols = norm.columns;
    db.exec(`DROP TABLE IF EXISTS ${ident(name)}`);
    db.exec(`CREATE TABLE ${ident(name)} (${cols.map(ident).join(", ")})`);
    if (!norm.rows.length) return;
    const stmt = db.prepare(`INSERT INTO ${ident(name)} VALUES (${cols.map(() => "?").join(", ")})`);
    try {
      db.exec("BEGIN");
      for (const row of norm.rows) {
        stmt.bind(cols.map((c) => sqlVal(row[c]))).step();
        stmt.reset(true);
      }
      db.exec("COMMIT");
    } finally {
      stmt.finalize();
    }
  }

  /** Run SQL → WbQueryResult (row-major arrays + per-column inferred types). */
  async query(sql, params = []) {
    const { db } = await bootSqlite();
    const columns = [];
    const rows = db.exec({
      sql,
      bind: params && params.length ? params : undefined,
      rowMode: "array",
      columnNames: columns,
      returnValue: "resultRows",
    });
    const types = columns.map((_c, j) => inferType(rows.map((r) => r[j])));
    return { columns, rows, types, rowCount: rows.length, engine: "sqlite-wasm", sql };
  }
}

function ident(name) { return '"' + String(name).replace(/"/g, '""') + '"'; }

/** Coerce a JS value to something sqlite-wasm can bind (no booleans/objects). */
function sqlVal(v) {
  if (v == null) return null;
  if (typeof v === "boolean") return v ? 1 : 0;
  if (typeof v === "number" || typeof v === "string" || typeof v === "bigint") return v;
  return JSON.stringify(v);
}

// data-viz · the POWERED tier — Observable Plot behind the <work-chart> floor.
//
// The floor (wb-chart.js `_drawXY`/`_drawPie`) is a zero-dependency SVG renderer
// themed entirely from --work-*. This module is the powered alternative: it draws
// the SAME logical chart (same series / categories / domain / labels off the SAME
// `_layout()` model) with Observable Plot — only the drawing changes, never the
// public API or the data path.
//
// Lazy-loaded from a CDN ESM at runtime (mirrors sqlite-wasm / wavelet): nothing
// is bundled, no dep is installed. `loadPlot()` is a single-flight import() that
// resolves to the Plot namespace, overridable via `window.__WB_PLOT__` (tests /
// offline hosts inject their own). If the import fails (network-blocked, the
// gate's wasm/floor proof), the caller silently falls back to the floor SVG.
//
// THEMING (gate-a, token-leak): Plot ships its own default colors + injects its
// own <style>. We never let a literal leak — every color/scheme/font Plot uses is
// READ from the element's computed --work-* tokens (readTokens) and passed as
// Plot's `color.range` / `style` / explicit per-mark `fill`/`stroke`. So the Plot
// render re-themes light/dark/signal exactly like the floor.
//
// SCOPE (gate-b): Plot returns a <figure> whose <style> lives INSIDE the figure
// subtree. We append that figure into the element's SHADOW root, so the style is
// shadow-scoped — nothing lands in document.head.

const PLOT_CDN = "https://esm.sh/@observablehq/plot@0.6";

let _plotPromise = null;

/**
 * Single-flight lazy import of Observable Plot. Resolves to the Plot namespace.
 * Overridable for tests / offline hosts via `window.__WB_PLOT__`.
 * Throws (rejects) when the chunk can't load — the caller falls back to the floor.
 */
export function loadPlot() {
  const override = typeof window !== "undefined" && window.__WB_PLOT__;
  if (override) return Promise.resolve(override);
  if (!_plotPromise) {
    _plotPromise = import(/* @vite-ignore */ PLOT_CDN).catch((e) => {
      _plotPromise = null; // allow a later retry
      throw e;
    });
  }
  return _plotPromise;
}

// Read the resolved --work-* token VALUES off the element (computed style). Plot
// gets concrete colors/fonts, never `var(--work-*)` strings (Plot writes them into
// its own generated stylesheet where the cascade context differs). Reading the
// computed value keeps Plot's paint locked to the active theme — flip the theme,
// re-read, re-draw → the chart re-themes (the flip-delta gate passes).
export function readTokens(el) {
  const cs = getComputedStyle(el);
  const v = (name, fallback) => (cs.getPropertyValue(name).trim() || fallback);
  return {
    fg:        v("--work-fg", "#121316"),
    fgMuted:   v("--work-fg-muted", "rgba(18,19,22,0.6)"),
    fgSubtle:  v("--work-fg-subtle", "rgba(18,19,22,0.38)"),
    surface:   v("--work-surface", "#ffffff"),
    border:    v("--work-border", "rgba(18,19,22,0.13)"),
    borderStrong: v("--work-border-strong", "rgba(18,19,22,0.28)"),
    font:      v("--work-font", "system-ui, sans-serif"),
    fontMono:  v("--work-font-mono", "ui-monospace, monospace"),
    textSm:    v("--work-text-sm", "12.5px"),
    // categorical palette — the SAME token order as the floor's PALETTE
    palette: [
      v("--work-brand", "#13d943"),
      v("--work-chip-blue", "#aecbf2"),
      v("--work-chip-peach", "#f3cfae"),
      v("--work-chip-lavender", "#d4c9f0"),
      v("--work-chip-green", "#b6e2bd"),
      v("--work-warn", "#b8861b"),
      v("--work-ok", "#0fae38"),
      v("--work-err", "#c92f2f"),
    ],
  };
}

// The shared Plot `style` object — drives Plot's own injected stylesheet from
// tokens so NO literal/default color leaks (gate-a).
function plotStyle(tk, height) {
  return {
    background: "transparent",
    color: tk.fgMuted,
    fontFamily: tk.font,
    fontSize: tk.textSm,
    overflow: "visible",
    width: "100%",
    height: height + "px",
    maxWidth: "100%",
  };
}

/**
 * Render `lay` (the floor's `_layout()` model) with Observable Plot into a fresh
 * <figure>, themed from `tk` (readTokens). Returns the figure element (the caller
 * mounts it in the SHADOW root). Pure — no DOM mutation outside the returned node.
 *
 * @param Plot   the loaded Observable Plot namespace
 * @param lay    { type, series:[{key,label,color,values}], categories, xVals,
 *                 xNumeric, fmt, xName }  — the floor's logical model
 * @param tk     readTokens(el)
 * @param opts   { width, height, format, legend }
 */
export function renderPlot(Plot, lay, tk, opts) {
  const { type, series, categories } = lay;
  const W = opts.width, H = opts.height;
  const fmtTick = (v) => fmtVal(v, opts.format);

  if (type === "pie") return renderPie(Plot, lay, tk, opts);

  // long-form tidy data: one row per (series, category) — the shape Plot wants.
  const data = [];
  series.forEach((s) => {
    s.values.forEach((val, i) => {
      if (val == null) return;
      data.push({
        series: s.label,
        // x is categorical (ordinal) unless this is a numeric scatter
        x: lay.xNumeric ? lay.xVals[i] : String(categories[i]),
        y: val,
      });
    });
  });

  const range = series.map((s) => s.color);
  const colorOpt = {
    range,
    legend: opts.legend !== "off" && series.length > 1,
  };

  const marks = [
    Plot.gridY({ stroke: tk.border, strokeOpacity: 1 }),
    Plot.ruleY([0], { stroke: tk.borderStrong }),
  ];

  if (type === "bar") {
    // grouped bars when multi-series: Plot's fx facets each category, dodge inside
    marks.push(Plot.barY(data, { x: "x", y: "y", fill: "series" }));
  } else if (type === "line") {
    marks.push(Plot.line(data, { x: "x", y: "y", z: "series", stroke: "series", strokeWidth: 2, curve: "linear" }));
    marks.push(Plot.dot(data, { x: "x", y: "y", fill: "series", r: 2.5, stroke: tk.surface, strokeWidth: 1 }));
  } else if (type === "area") {
    marks.push(Plot.areaY(data, { x: "x", y: "y", z: "series", fill: "series", fillOpacity: 0.16 }));
    marks.push(Plot.line(data, { x: "x", y: "y", z: "series", stroke: "series", strokeWidth: 2 }));
  } else if (type === "scatter") {
    marks.push(Plot.dot(data, { x: "x", y: "y", fill: "series", r: 5, stroke: tk.surface, strokeWidth: 1 }));
  }

  const spec = {
    width: W,
    height: H,
    marginLeft: 56,
    marginBottom: 36,
    style: plotStyle(tk, H),
    color: colorOpt,
    x: {
      label: null,
      type: lay.xNumeric ? "linear" : "band",
      tickFormat: lay.xNumeric ? ((v) => fmtVal(v, "num")) : undefined,
    },
    y: { label: null, grid: false, tickFormat: fmtTick },
    marks,
  };

  const fig = Plot.plot(spec);
  themeFigure(fig, tk);
  return fig;
}

function renderPie(Plot, lay, tk, opts) {
  const { categories, series } = lay;
  const s = series[0] || { values: [] };
  const data = categories.map((c, i) => ({
    label: String(c),
    value: s.values[i] == null ? 0 : Math.max(0, s.values[i]),
  })).filter((d) => d.value > 0);
  const total = data.reduce((a, d) => a + d.value, 0) || 1;
  const range = data.map((_, i) => tk.palette[i % tk.palette.length]);

  // Plot has no native pie. The gate compares the LOGICAL model (labels/values),
  // not the glyph — so we still render a real donut by drawing arc <path>s into a
  // bare Plot figure (keeps the shadow-scoped figure + Plot's chrome conventions).
  let a0 = -Math.PI / 2;
  const cx = opts.width / 2, cy = opts.height / 2;
  const R = Math.min(opts.width, opts.height) / 2 - 14, r0 = R * 0.56;
  const arcs = data.map((d, i) => {
    const frac = d.value / total;
    const a1 = a0 + frac * Math.PI * 2;
    const large = a1 - a0 > Math.PI ? 1 : 0;
    const p = (ang, rad) => [cx + Math.cos(ang) * rad, cy + Math.sin(ang) * rad];
    const [x0, y0] = p(a0, R), [x1, y1] = p(a1, R);
    const [x2, y2] = p(a1, r0), [x3, y3] = p(a0, r0);
    const path = `M${x0},${y0} A${R},${R} 0 ${large} 1 ${x1},${y1} L${x2},${y2} A${r0},${r0} 0 ${large} 0 ${x3},${y3} Z`;
    a0 = a1;
    return { path, fill: range[i] };
  });

  const fig = Plot.plot({
    width: opts.width,
    height: opts.height,
    style: plotStyle(tk, opts.height),
    marks: [Plot.frame({ stroke: "none" })],
  });
  const svg = fig.querySelector("svg") || fig;
  const NS = "http://www.w3.org/2000/svg";
  arcs.forEach((arc) => {
    const path = document.createElementNS(NS, "path");
    path.setAttribute("d", arc.path);
    path.setAttribute("fill", arc.fill);
    svg.appendChild(path);
  });
  const t1 = document.createElementNS(NS, "text");
  t1.setAttribute("x", cx); t1.setAttribute("y", cy - 2);
  t1.setAttribute("text-anchor", "middle");
  t1.setAttribute("fill", tk.fg);
  t1.setAttribute("font-weight", "600"); t1.setAttribute("font-size", "18");
  t1.setAttribute("font-family", tk.font);
  t1.textContent = fmtVal(total, opts.format);
  svg.appendChild(t1);
  const t2 = document.createElementNS(NS, "text");
  t2.setAttribute("x", cx); t2.setAttribute("y", cy + 16);
  t2.setAttribute("text-anchor", "middle");
  t2.setAttribute("fill", tk.fgMuted);
  t2.setAttribute("font-size", "11"); t2.setAttribute("font-family", tk.fontMono);
  t2.textContent = "total";
  svg.appendChild(t2);
  themeFigure(fig, tk);
  return fig;
}

// Drive Plot's own figure chrome (the legend swatches + caption text Plot styles
// via its injected <style>) from tokens — belt-and-suspenders so even Plot's own
// stylesheet paints from --work-* values, leaving zero default-color leak.
function themeFigure(fig, tk) {
  fig.style.setProperty("color", tk.fgMuted);
  fig.style.setProperty("font-family", tk.font);
  fig.style.setProperty("background", "transparent");
  // Plot writes its swatch/axis colors into <style> inside the figure; nudge any
  // text node Plot left without an explicit fill onto a token value.
  fig.querySelectorAll("svg text").forEach((t) => {
    if (!t.getAttribute("fill")) t.setAttribute("fill", tk.fgMuted);
  });
}

// shared value formatter — mirrors the floor's fmtVal so axis ticks read identically.
function fmtVal(v, format) {
  if (v == null) return "";
  const n = Number(v);
  if (format === "usd") return "$" + abbrev(n);
  if (format === "pct") return (n * (Math.abs(n) <= 1 ? 100 : 1)).toFixed(1) + "%";
  if (format === "num") return abbrev(n);
  return Number.isInteger(n) ? n.toLocaleString() : abbrev(n);
}
function abbrev(n) {
  const a = Math.abs(n);
  if (a >= 1e9) return (n / 1e9).toFixed(1).replace(/\.0$/, "") + "B";
  if (a >= 1e6) return (n / 1e6).toFixed(1).replace(/\.0$/, "") + "M";
  if (a >= 1e3) return (n / 1e3).toFixed(1).replace(/\.0$/, "") + "k";
  return Number.isInteger(n) ? n.toLocaleString() : n.toLocaleString(undefined, { maximumFractionDigits: 2 });
}
